#include <stdio.h>
#include <string.h>

char S[1010];
char cur[1012];
int N;

/* Tenta usar como A o prefixo de S com L digitos */
int try(int L){
    int len = L, pos = L;
    while (pos < N) {
        /* incrementa cur (numero atual) */
        int i = len - 1;
        while (i >= 0 && cur[i] == '9') { cur[i] = '0'; i--; }
        if (i >= 0) {
            cur[i]++;
        } else {
            /* 999...9 -> 1000...0 : ganha um digito */
            memmove(cur + 1, cur, len);
            cur[0] = '1';
            len++;
        }
        if (pos + len > N) return 0;
        if (memcmp(S + pos, cur, len) != 0) return 0;
        pos += len;
    }
    return 1;
}

int main(void){
    if (scanf("%d", &N) != 1) return 0;
    for (int i = 0; i < N; i++){
        int d;
        scanf("%d", &d);
        S[i] = (char)('0' + d);
    }
    S[N] = 0;

    if (S[0] == '0') {
        /* A >= 1 nao pode comecar com 0; entrada garantidamente valida,
           mas por seguranca imprimimos a propria string */
        printf("%s\n", S);
        return 0;
    }

    /* O menor A corresponde ao menor comprimento de prefixo que funciona */
    for (int L = 1; L <= N; L++){
        memcpy(cur, S, L);
        cur[L] = 0;
        if (try(L)){
            S[L] = 0;
            printf("%s\n", S);
            return 0;
        }
    }

    printf("%s\n", S); /* fallback (nao deveria ocorrer em entradas validas) */
    return 0;
}
